#### SlowProjectiles
public class SlowProjectiles : Item
{
	public static string staticID = "SlowProjectiles";
	private float speedMultiplier = 0.4f;
	public SlowProjectiles()
	{
		isCursed = true;
		hubOnly = true;
		ID = staticID;
		category = Category.Misc;
	}
	public override void Activate()
	{
		Projectile.projectileShootEvent = (Projectile.ProjectileShootEvent)Delegate.Remove(Projectile.projectileShootEvent, new Projectile.ProjectileShootEvent(ModifyProjectileSpeed));
		Projectile.projectileShootEvent = (Projectile.ProjectileShootEvent)Delegate.Combine(Projectile.projectileShootEvent, new Projectile.ProjectileShootEvent(ModifyProjectileSpeed));
	}
	public override void Deactivate()
